catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMCoChairUtils');

    ga.addParam('sysparm_name', 'getCoChairNames');
    ga.addParam('sysparm_cmn_location_sys_id', newValue);
    ga.getXML(function(serverResponse) {
        var response = JSON.parse(serverResponse.responseXML.documentElement.getAttribute("answer"));

        g_form.setValue('employee_co_chair', response.employee);
        g_form.setValue('employer_co_chair', response.employer);
        g_form.setValue('hs_representative', response.representative);
    });
}
